<script setup lang="ts">
import{computed,ref}from'vue';import{useCommunityStore}from'./stores/community';import{communities,communityById,wants}from'./data/market';import{MapPin,ChevronDown,Search,Plus,Sparkles,ArrowUpRight,Heart,MessageCircle,Store,Radio,X,ArrowLeftRight,Bot}from'lucide-vue-next';
const store=useCommunityStore();const picker=ref(false);const search=ref('');const category=ref('全部');const query=ref('');const aiNote=ref('');const categories=['全部','家具家居','家用电器','母婴玩具','运动户外'];const activeProducts=computed(()=>store.recommendedProducts.filter(p=>(category.value==='全部'||p.category===category.value)&&(!search.value||p.title.includes(search.value)||p.category.includes(search.value))));const crossCount=computed(()=>store.recommendedProducts.filter(p=>p.community_id!==store.activeId).length);const sourceLabel=(id:string)=>communityById(id).name;
function askAI(){const q=query.value.trim();if(!q)return;const matches=store.recommendedProducts.filter(p=>(q.includes('冰箱')?p.title.includes('冰箱'):p.title.includes(q)||p.category.includes(q)));aiNote.value=matches.length?'找到 '+matches.length+' 件相关闲置：'+matches.map(p=>p.title+'（'+sourceLabel(p.community_id)+'，¥'+p.price+'）').join('；'):'暂时没有匹配商品，已记录这条需求（演示环境）。';}
function scrollMarket(){document.getElementById('market')?.scrollIntoView({behavior:'smooth'})}
</script>
<template><div class="app-shell" :class="{'scene-switching':store.switching}">
<header class="topbar"><a class="brand" href="#"><span class="brand-mark">拾</span><span><b>拾光集市</b><small>把好物，留在邻里之间</small></span></a><div class="top-actions"><span class="online-dot"></span><span class="online-text">邻里集市正在营业</span><button class="publish-btn"><Plus :size="16"/>发布闲置</button><div class="avatar">邻</div></div></header>
<main><section class="hero"><div class="hero-copy"><div class="eyebrow"><span class="eyebrow-line"></span>TONGZHOU · NEIGHBORHOOD MARKET</div><div class="community-title"><div><h1>{{store.active.name}}<span class="title-dot">.</span></h1><p class="location"><MapPin :size="14"/>{{store.active.city}} · {{store.active.district}} <span class="sep">/</span> 邻里集市</p></div><button class="switch-trigger" @click="picker=!picker"><ArrowLeftRight :size="15"/>切换社区<ChevronDown :size="14"/></button></div><p class="hero-desc">每一件闲置，都可能是另一位邻居<br/>正在寻找的生活答案。</p><div class="hero-stats"><div><b>{{store.localProducts.length+18}}</b><span>本社区闲置</span></div><i></i><div><b>{{wants.filter(w=>w.community_id===store.activeId).length+6}}</b><span>邻里正在求购</span></div><i></i><div><b>今日 {{store.localProducts.length+3}}</b><span>新增好物</span></div></div><div class="hero-cta"><button class="dark-btn" @click="scrollMarket">逛逛本社区 <ArrowUpRight :size="16"/></button><span><Sparkles :size="14"/>AI 正在帮你发现邻里好物</span></div></div>
<div class="scene-wrap"><div class="scene-label"><span>COMMUNITY SCENE</span><span>01 / 02</span></div><div class="scene-orbit orbit-one"></div><div class="scene-orbit orbit-two"></div><div class="scene-ground"></div><div class="scene-building"><div class="roof"></div><div class="building-body"><div class="building-band"></div><div class="windows"><i v-for="n in 12" :key="n"></i></div><div class="entrance"></div></div><div class="building-side"></div></div><div class="scene-tree tree-a"></div><div class="scene-tree tree-b"></div><div class="scene-path"></div><div class="scene-caption"><span class="scene-pin"><MapPin :size="13"/></span><div><b>{{store.active.name}}</b><small>街坊邻里 · 好物循环</small></div></div><div class="scene-stamp">邻<br/>里<br/>有<br/>光</div></div>
<div v-if="picker" class="community-picker"><div class="picker-head"><div><small>CHOOSE YOUR NEIGHBORHOOD</small><b>选择你要逛的社区</b></div><button @click="picker=false"><X :size="18"/></button></div><button v-for="c in communities" :key="c.id" class="community-option" :class="{selected:store.activeId===c.id,disabled:c.status!=='open'}" @click="store.switchCommunity(c.id);if(c.status==='open')picker=false"><span class="option-scene" :style="{background:c.accent}"><Store :size="20"/></span><span class="option-text"><b>{{c.name}}</b><small>{{c.city}} · {{c.district}} · {{c.status==='open'?'集市开放中':'即将开放'}}</small></span><span class="option-status">{{c.status==='open'?(store.activeId===c.id?'当前社区':'进入社区'):'敬请期待'}}</span></button><p class="picker-foot">新社区持续接入中 · 仅开放社区展示真实商品</p></div></section>
<section class="market-tools" id="market"><div class="section-heading"><div><span class="section-kicker">THE NEIGHBORHOOD MARKET</span><h2>在邻里间，发现好物</h2></div><span class="fresh-tag"><span></span>实时更新 · 社区独立展示</span></div><div class="market-layout"><div class="market-main"><div class="filter-row"><div class="category-tabs"><button v-for="c in categories" :key="c" :class="{active:category===c}" @click="category=c">{{c}}</button></div><div class="searchbox"><Search :size="16"/><input v-model="search" placeholder="搜一搜邻居的闲置"/></div></div><div class="product-grid"><article v-for="p in activeProducts" :key="p.id" class="product-card"><div class="product-image"><img :src="p.image" :alt="p.title" loading="lazy"/><span class="condition">{{p.condition}}</span><button class="like"><Heart :size="16"/></button><span v-if="p.community_id!==store.activeId" class="cross-tag">跨社区发现</span></div><div class="product-info"><div class="product-category">{{p.category}} <span>·</span> {{p.source}}</div><h3>{{p.title}}</h3><div class="price-row"><b>¥{{p.price}}</b><del v-if="p.originalPrice">¥{{p.originalPrice}}</del></div><div class="product-meta"><span><MapPin :size="12"/>{{sourceLabel(p.community_id)}}</span><span>{{p.postedAt}}</span></div></div></article></div><div v-if="!activeProducts.length" class="empty-state">暂时没有符合条件的商品，换个关键词试试。</div></div>
<aside class="side-column"><div class="ai-card"><div class="ai-card-head"><div class="ai-icon"><Sparkles :size="18"/></div><span>拾光 AI · 智能寻物</span><span class="live-pill">LIVE</span></div><h3>你在找什么？</h3><p>先搜本社区，再帮你看看附近邻居有没有。</p><div class="ai-search"><input v-model="query" placeholder="例如：想找一台小冰箱"/><button @click="askAI"><ArrowUpRight :size="17"/></button></div><div v-if="aiNote" class="ai-result">{{aiNote}}</div><div class="ai-modes"><button v-for="m in [{id:'local',name:'仅本社区'},{id:'nearby',name:'附近社区'},{id:'all',name:'全部社区'}]" :key="m.id" :class="{active:store.mode===m.id}" @click="store.mode=m.id as 'local'|'nearby'|'all'">{{m.name}}</button></div><div class="ai-foot"><Bot :size="14"/>平台级 AI 调度 · {{crossCount}} 件跨社区发现</div></div>
<div class="want-card"><div class="want-head"><div><span class="section-kicker">NEIGHBORS ARE LOOKING FOR</span><h3>邻居正在求购</h3></div><ArrowUpRight :size="17"/></div><div v-for="w in wants.filter(w=>w.community_id===store.activeId)" :key="w.id" class="want-item"><span class="want-dot"></span><div><b>{{w.title}}</b><p>{{w.detail}}</p><small>{{w.time}}</small></div></div><div class="want-bottom">让闲置遇见需要，让邻里彼此照应</div></div></aside></div></section></main>
<footer><div class="footer-brand"><span class="brand-mark">拾</span><b>次渠·拾光集市</b></div><span>让好物循环，让邻里有光</span><span>社区数据独立 · 邻里交易更安心</span></footer></div></template>